#include <stdio.h>

void min_max(const int values[], int count, int *min, int *max) {
    *min = *max = values[0];
    for (int i = 1; i < count; i++) {
        if (values[i] < *min) *min = values[i];
        if (values[i] > *max) *max = values[i];
    }
}

int main() {
    int v[] = {9, 2, 14, 7, 3};
    int lowest, highest;
    min_max(v, 5, &lowest, &highest);
    printf("%d %d\n", highest, lowest);
    return 0;
}
